<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Spatie\Permission\Models\Role;
class UserController extends Controller {public function index(){return User::with('roles','companies')->paginate(50);}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|string|min:12','role'=>'required|exists:roles,name','company_ids'=>'array','company_ids.*'=>'uuid|exists:companies,id']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);$u->assignRole($d['role']);$u->companies()->sync($d['company_ids']??[]);return response()->json($u->load('roles','companies'),201);}public function update(Request $r,User $user){$d=$r->validate(['name'=>'sometimes|string','email'=>'sometimes|email|unique:users,email,'.$user->id,'password'=>'nullable|string|min:12','role'=>'sometimes|exists:roles,name','company_ids'=>'sometimes|array','active'=>'sometimes|boolean']);if(!empty($d['password']))$d['password']=Hash::make($d['password']);$user->update(collect($d)->except(['role','company_ids'])->all());if(isset($d['role']))$user->syncRoles([$d['role']]);if(isset($d['company_ids']))$user->companies()->sync($d['company_ids']);return $user->load('roles','companies');}public function roles(){return Role::with('permissions')->get();}}
